'use client';

import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import Link from 'next/link';

interface Problem {
    id: string;
    contestId: number;
    index: string;
    name: string;
    rating: number;
    tags: string[];
    link: string;
}

export default function PlaylistPage() {
    const [topic, setTopic] = useState('');
    const [playlist, setPlaylist] = useState<Problem[]>([]);
    const [loading, setLoading] = useState(false);
    const [searched, setSearched] = useState(false);

    const generatePlaylist = async () => {
        if (!topic.trim()) return;
        setLoading(true);
        setPlaylist([]);
        setSearched(true);

        try {
            const res = await fetch('/api/playlist/generate', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ topic }),
            });
            const data = await res.json();
            if (data.playlist) {
                setPlaylist(data.playlist);
            }
        } catch (e) {
            console.error(e);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="min-h-screen bg-black text-white p-6 md:p-12 font-sans">
            {/* Header */}
            <header className="flex items-center justify-between mb-16">
                <div>
                    <h1 className="text-4xl md:text-6xl font-black tracking-tighter text-transparent bg-clip-text bg-gradient-to-r from-emerald-400 to-cyan-400">
                        SMART PLAYLIST
                    </h1>
                    <p className="text-gray-400 mt-2 text-lg">
                        AI-Curated Problem Sets for Specific Topics.
                    </p>
                </div>
                <Link href="/dashboard" className="text-gray-500 hover:text-white transition-colors">
                    Back to Dojo
                </Link>
            </header>

            {/* Search Section */}
            <div className="max-w-3xl mx-auto mb-20 text-center">
                <h2 className="text-2xl font-bold mb-6">What do you want to master today?</h2>
                <div className="relative group">
                    <div className="absolute -inset-1 bg-gradient-to-r from-emerald-600 to-cyan-600 rounded-lg blur opacity-25 group-hover:opacity-75 transition duration-1000 group-hover:duration-200"></div>
                    <div className="relative flex items-center bg-zinc-900 rounded-lg overflow-hidden border border-zinc-800 p-2">
                        <input
                            type="text"
                            value={topic}
                            onChange={(e) => setTopic(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && generatePlaylist()}
                            className="bg-transparent text-white w-full px-4 py-3 text-xl focus:outline-none placeholder-zinc-600"
                            placeholder="e.g., Digit DP, Centroid Decomposition, Min-Cost Max-Flow..."
                        />
                        <button
                            onClick={generatePlaylist}
                            disabled={loading}
                            className={`px-8 py-3 rounded-md font-bold transition-all ${loading
                                    ? 'bg-zinc-800 text-zinc-500 cursor-not-allowed'
                                    : 'bg-emerald-500 text-black hover:bg-emerald-400 hover:scale-105 active:scale-95'
                                }`}
                        >
                            {loading ? 'DIGGING...' : 'GENERATE'}
                        </button>
                    </div>
                </div>

                {/* Quick Tags */}
                <div className="flex flex-wrap justify-center gap-3 mt-6">
                    {['Dynamic Programming', 'Graph Theory', 'Segment Trees', 'Game Theory', 'Bitmasking'].map(t => (
                        <button
                            key={t}
                            onClick={() => { setTopic(t); generatePlaylist(); }}
                            className="px-4 py-1.5 rounded-full border border-zinc-800 hover:border-emerald-500/50 hover:bg-emerald-500/10 text-sm text-zinc-400 transition-colors"
                        >
                            {t}
                        </button>
                    ))}
                </div>
            </div>

            {/* Results Grid */}
            <div className="max-w-6xl mx-auto">
                {loading && (
                    <div className="flex flex-col items-center justify-center py-20 space-y-4">
                        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-emerald-500"></div>
                        <p className="text-zinc-500 animate-pulse">Consulting the Grand Archives...</p>
                    </div>
                )}

                {!loading && searched && playlist.length === 0 && (
                    <div className="text-center py-20 text-zinc-500">
                        <p>No clean matches found. Try a broader topic name.</p>
                    </div>
                )}

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    <AnimatePresence>
                        {playlist.map((p, i) => (
                            <motion.a
                                key={p.id}
                                href={p.link}
                                target="_blank"
                                rel="noopener noreferrer"
                                initial={{ opacity: 0, y: 20 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ delay: i * 0.05 }}
                                className="group relative bg-zinc-900/50 border border-zinc-800 rounded-xl p-6 hover:bg-zinc-900 hover:border-emerald-500/30 transition-all duration-300"
                            >
                                <div className="flex justify-between items-start mb-4">
                                    <span className={`text-xs font-bold px-2 py-1 rounded ${getRatingColor(p.rating)}`}>
                                        {p.rating || 'UNRATED'}
                                    </span>
                                    <span className="text-zinc-600 text-xs font-mono">{p.id}</span>
                                </div>
                                <h3 className="text-xl font-bold mb-2 group-hover:text-emerald-400 transition-colors">
                                    {p.name}
                                </h3>
                                <div className="flex flex-wrap gap-2 mt-4">
                                    {p.tags.slice(0, 3).map(tag => (
                                        <span key={tag} className="text-xs text-zinc-500 bg-zinc-800/50 px-2 py-1 rounded">
                                            {tag}
                                        </span>
                                    ))}
                                </div>
                            </motion.a>
                        ))}
                    </AnimatePresence>
                </div>
            </div>
        </div>
    );
}

function getRatingColor(r: number) {
    if (r < 1200) return 'bg-gray-800 text-gray-300';
    if (r < 1400) return 'bg-green-900 text-green-300';
    if (r < 1600) return 'bg-cyan-900 text-cyan-300';
    if (r < 1900) return 'bg-blue-900 text-blue-300';
    if (r < 2100) return 'bg-purple-900 text-purple-300';
    if (r < 2400) return 'bg-orange-900 text-orange-300';
    return 'bg-red-900 text-red-300';
}
